head.script:
// 테스트 설명, 유효성 값 설정
//  - _1 : 속성값(true / false / 미설정) 동작 + GridViewItemSet 무시
//  - _2 : 입력 형식 관련 (checkcomboboxRangeSeparator 범위 선택, displayMode + delimiter, 동일 라벨 아이템)
scwin.tData = {
    "description" : "[column > P > checkcomboboxUseEdit]<br/>inputType='checkcombobox' 인 Column 에서 값을 직접 입력하여 아이템을 선택하는 기능을 허용할지 설정합니다.",
    "validation" : [
        "true 설정 시, Column 에서 아이템 리스트창이 표시되었을때 라벨 표시 영역을 클릭하면 편집 기능이 활성화 됩니다.",
        "true 설정 시, 편집 기능이 활성화 되면 아이템 라벨값과 Column 의 separator 속성값을 직접 입력하여 한 개 이상의 아이템을 선택할 수 있습니다.",
        "true 설정 시, 라벨 표시 영역 편집창에서 Enter 키를 입력하거나 아이템 리스트창을 닫아 수정된 입력값을 Column 에 반영합니다.",
        "false 설정 시, 아이템 리스트창의 라벨 표시 영역 편집 기능을 활성화하지 않습니다.",
        "미설정 시, 아이템 리스트창의 라벨 표시 영역 편집 기능을 활성화하지 않습니다.",
        "false 설정 시, 아이템 리스트창에서 아이템을 선택/해제한 후 Column 에 반영합니다.",
        "Column 의 아이템이 GridViewItemSet 으로 정의된 경우 GridView 팝업창이 표시되므로 checkcomboboxUseEdit 속성이 무시됩니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (true / 기본 아이템 / separator 미설정)
    con_checkcomboboxUseEdit.setValue("2");
    con_itemDefinition.setValue("item");
    con_separator.setValue("");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 아이템 1월 ~ 6월 (value 1 ~ 6)
scwin.itemCount = 6;
scwin.rowPattern = [
    { "name" : "선택 없음", "month" : [] },
    { "name" : "1월, 2월 선택", "month" : [1, 2] }
];



// comp 생성
//  - name  : 초기 선택 상태 설명 Column
//  - month : 검증 대상 Body Column (inputType=checkcombobox, 아이템 1월 ~ 6월)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof dlt_month !== 'undefined' && dlt_month) {
        $p.data.remove("dlt_month");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cUseEdit = con_checkcomboboxUseEdit.getText();
    let cItemDefinition = con_itemDefinition.getValue();
    let cSeparator = con_separator.getValue();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[절차] month 셀 더블클릭으로 아이템 리스트창 열기 -> 셀의 라벨 표시 영역 클릭 -> 편집창이면 라벨값과 separator 입력(예: 3월 4월, separator=, 이면 3월,4월) -> Enter 또는 셀 밖 클릭으로 리스트창 닫기\n[확인] 입력 중 리스트창 체크 상태, 편집 종료 후 출력되는 선택값/표시값\n[false/미설정] 라벨 표시 영역 클릭 시 편집창 없이 리스트창이 닫힘 -> 다시 열어 아이템 체크 선택/해제 후 닫기"', '', 'label1');

    // 바인딩 dataList (선택값은 Column 의 separator 로 연결, 미설정 시 기본 구분자 공백)
    let dataSeparator = (cSeparator === '') ? ' ' : cSeparator;
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="month" name="month" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON(scwin.rowPattern.map(function (row) {
        return { "name" : row.name, "month" : row.month.join(dataSeparator) };
    }), false);

    // 아이템 정의
    let strItems = '<w2:choices>';
    if (cItemDefinition === "gridViewItemset") {
        // GridViewItemSet : checkbox item 은 dataList 첫 컬럼(chk) 을 참조 (checkColumn=0)
        let strItemDlt = '';
        strItemDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_month" baseNode="list" repeatNode="map">';
        strItemDlt += '<w2:columnInfo>';
        strItemDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
        strItemDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
        strItemDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
        strItemDlt += '</w2:columnInfo>';
        strItemDlt += '<w2:data use="true"></w2:data>';
        strItemDlt += '</w2:dataList>';
        $p.data.create(strItemDlt);
        let arrItem = [];
        for (let i = 1; i <= scwin.itemCount; i++) {
            arrItem.push({ "chk" : "0", "value" : String(i), "label" : i + "월" });
        }
        dlt_month.setJSON(arrItem, false);

        strItems += '<w2:gridViewItemset nodeset="data:dlt_month" label="label" value="value" checkColumn="0">';
        strItems += '<w2:item header="선택" inputType="checkbox" ref="chk"></w2:item>';
        strItems += '<w2:item header="value" ref="value"></w2:item>';
        strItems += '<w2:item header="label" ref="label"></w2:item>';
        strItems += '</w2:gridViewItemset>';
    } else {
        for (let i = 1; i <= scwin.itemCount; i++) {
            strItems += '<w2:item><w2:label>' + i + '월</w2:label><w2:value>' + i + '</w2:value></w2:item>';
        }
    }
    strItems += '</w2:choices>';

    // month Column 속성
    let attrMonth = ' inputType="checkcombobox"';
    attrMonth += (cSeparator === '') ? '' : ' separator="' + cSeparator + '"';
    attrMonth += (cUseEdit === '') ? '' : ' checkcomboboxUseEdit="' + cUseEdit + '"';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:600px;height:150px;" ev:oneditend="scwin.target1_oneditend">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="220" style="" inputType="text" id="column1" value="초기 선택 상태"></w2:column>';
    strTarget += '<w2:column width="360" style="" inputType="text" id="column2" value="month (checkcombobox)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="220" style="" inputType="text" id="name" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="360" style="text-align:left;" id="month" value=""' + attrMonth + '>' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// month Column 셀의 표시 텍스트 (따옴표로 감싸 구분자 확인)
scwin.getCellText = function (rowIndex) {
    let td = document.querySelector("td[id*='" + target1.id + "_cell_" + rowIndex + "_1']");
    return td ? "'" + td.textContent + "'" : "셀 없음";
}



// validation 2, 3, 6, 7 : 편집 종료 후 해당 행 선택값과 셀 표시값
scwin.target1_oneditend = function (rowIndex, colIndex) {
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("편집 종료 후 " + rowIndex + "행 : 선택값 '" + dlt_bind.getCellData(rowIndex, "month") + "' -> 표시값 " + scwin.getCellText(rowIndex));
    }, 100);
}
